//! 🧪️ Actual Store leases bind original media snapshots and reject later issuer generations or same-value aliases.
use super::*;
#[test]fn actual_original_media_read_binds_pointer_and_current_issuer(){use std::sync::Arc;use store::os_store::snapshot_read::{SnapshotReadRegistryHandle,ErasedSnapshotRead,SnapshotReadRegistryAliasRetirement,snapshot_registry_alias_close_step};use semio_framework_value::RetainedCloneGrant;let grant=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128};let laws:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in laws["cases"].as_array().unwrap(){let payload=Arc::new(7u64);let alias=Arc::new(7u64);let registry=SnapshotReadRegistryHandle::new();assert!(registry.publish_authority(4,[17;32]));let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("original issuer"));let read=ErasedSnapshotRead::new(Arc::clone(&payload),lease).try_into_typed::<u64>().unwrap_or_else(|_|panic!("original typed source"));if !row["current"].as_bool().unwrap(){assert!(registry.publish_authority(5,[18;32]));}assert_eq!(media_original_read_matches(&read,if row["sameSnapshot"].as_bool().unwrap(){&payload}else{&alias},4,[17;32]),row["accept"].as_bool().unwrap());let(mut source,_)=read.admit_retained_clone_source(grant).unwrap_or_else(|_|panic!("funded source"));while !source.terminal_is_empty(){source.close_step(grant).unwrap();}assert!(registry.terminal_is_empty());drop(payload);drop(alias);let mut close=Some(SnapshotReadRegistryAliasRetirement::new(registry));while close.is_some(){snapshot_registry_alias_close_step(&mut close,grant).unwrap();}}}
